package com.hbm.missile.completion.volcano;
import com.hbm.hazard.HbmHazards;import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.level.material.MapColor;
/** Original BlockVolcano five visible modes and radioactive companion, not an inert item replacement. */
public final class VolcanoBlock extends BaseEntityBlock {
 public static final IntegerProperty META=IntegerProperty.create("legacy_meta",0,15);private static final MapCodec<VolcanoBlock> CODEC=simpleCodec(p->new VolcanoBlock(false));public final boolean radioactive;public VolcanoBlock(boolean radioactive){super(Properties.of().mapColor(MapColor.METAL).strength(-1,6000).sound(SoundType.STONE));this.radioactive=radioactive;registerDefaultState(stateDefinition.any().setValue(META,0));}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return CODEC;}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){builder.add(META);}@Override public BlockState getStateForPlacement(BlockPlaceContext context){return defaultBlockState().setValue(META,context.getItemInHand().getOrDefault(HbmHazards.LEGACY_METADATA.get(),0)&15);}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new VolcanoBlockEntity(pos,state);}@Override public RenderShape getRenderShape(BlockState state){return RenderShape.MODEL;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return level.isClientSide?null:createTickerHelper(type,VolcanoContent.ENTITY.get(),VolcanoBlockEntity::tick);}public static boolean growing(int meta){return meta==2||meta==3;}public static boolean extinguishing(int meta){return meta==1||meta==3;}
}
